import RNA, random, sys, time
target = "((..(((((........(.((..((.(.....(....).((((((((.........((......((((.....))))......))...((..((.......(..(......)..)..((..((.....((....)).((((.....(((.....(..((.(...).))..).....))).((((...(.......(..(.((...)).)..).......)...))))........)))).....((((((...)))))).))..))...........))..)).........(..((((....))((((((.....(........).....))))))..))..)...))))))))........).))..)).).....(.......).)))))..))."
n=len(target)
seed=int(sys.argv[1]); warm=sys.argv[2]
random.seed(seed)
# build pair map
stack=[]; pairs={}
for i,c in enumerate(target):
    if c=='(': stack.append(i)
    elif c==')':
        j=stack.pop(); pairs[j]=i; pairs[i]=j
comp={'G':'C','C':'G','A':'U','U':'A'}
s=list(warm)
fc=RNA.fold_compound(''.join(s)); ss,mfe=fc.mfe()
cur_d=RNA.bp_distance(ss,target)
best_d=cur_d; best=''.join(s)
t0=time.time(); TIME=120; it=0; T=1.2
while time.time()-t0<TIME and best_d>0:
    it+=1
    fc=RNA.fold_compound(''.join(s)); ss,mfe=fc.mfe()
    cur_d=RNA.bp_distance(ss,target)
    # identify missing target pairs (both ends unpaired in ss but target wants pair)
    # and spurious pairs
    # ss pairs
    sspr=set(); st=[]
    for k,c in enumerate(ss):
        if c=='(': st.append(k)
        elif c==')':
            j=st.pop(); sspr.add((j,k)); sspr.add((k,j))
    tpr=set()
    for i,j in pairs.items():
        if i<j: tpr.add((i,j)); tpr.add((j,i))
    missing=[(i,pairs[i]) for i in range(n) if i in pairs and (i,pairs[i]) not in sspr and i<pairs[i]]
    spurious=[(j,k) for (j,k) in sspr if (j,k) not in tpr and j<k]
    if not missing and not spurious:
        best_d=0; best=''.join(s); break
    cand=s[:]
    # repair: for a missing pair, set both to G-C (random orientation)
    r=random.random()
    if missing and (r<0.6 or not spurious):
        i,j=random.choice(missing)
        if random.random()<0.5:
            cand[i]='G'; cand[j]='C'
        else:
            cand[i]='C'; cand[j]='G'
    else:
        # break spurious: mutate one end to mismatch its target partner's partner
        i,j=random.choice(spurious)
        cand[i]=random.choice('ACGU')
    fc2=RNA.fold_compound(''.join(cand)); ss2,mfe2=fc2.mfe()
    nd=RNA.bp_distance(ss2,target)
    if nd<=cur_d or random.random()<pow(2.718,-(nd-cur_d)/T):
        s=cand; cur_d=nd
        if nd<best_d:
            best_d=nd; best=''.join(s)
    T*=0.9995
print(f"S{seed} B{best_d} {best}", flush=True)
PYEOF
